            "ห้าม Crop เปลี่ยนสี Retouch ลบลายน้ำ หรือดัดแปลงผลงานที่มีลิขสิทธิ์ของผู้อื่นเพื่อทำให้ดูเหมือนเป็นผลงานใหม่",
            "จัดเก็บหลักฐานใบอนุญาต หนังสือยินยอม Model Release และข้อตกลงกับช่างภาพไว้ในเอกสารของบริษัท",
