export function getDocsContent({
  categoryId,

  articleId,

  locale = "en",
}) {
  const content = DOCS_CONTENT[`${categoryId}/${articleId}`];

  if (!content) {
    return null;
  }

  const safeLocale = locale === "th" ? "th" : "en";

  function localize(value) {
    if (!value) {
      return value;
    }

    if (
      typeof value === "object" &&
      !Array.isArray(value) &&
      ("en" in value || "th" in value)
    ) {
      return value[safeLocale] || value.en || value.th;
    }

    return value;
  }

  return {
    ...content,

    eyebrow: localize(content.eyebrow),

    title: localize(content.title),

    description: localize(content.description),

    introduction: localize(content.introduction),

    highlights: (content.highlights || []).map((item) => ({
      ...item,

      title: localize(item.title),

      description: localize(item.description),
    })),

    sections: (content.sections || []).map((section) => ({
      ...section,

      title: localize(section.title),

      paragraphs: localize(section.paragraphs),

      items: localize(section.items),

      steps: localize(section.steps),

      notes: localize(section.notes),

      images: (section.images || []).map((image) => ({
        ...image,

        title: localize(image.title),

        alt: localize(image.alt),

        caption: localize(image.caption),
      })),
    })),
  };
}
